{
  "cvars": {
    "ivs": [
      {
        "description": "Student-teacher ratio measured as number of students per teacher in the district (higher = more students per teacher, i.e., larger class sizes). Calculated as students / teachers.",
        "columns": [
          "StudentTeacherRatio"
        ]
      }
    ],
    "dv": {
      "description": "Average academic performance measured as the mean of the district average reading and math Stanford-9 scores.",
      "columns": [
        "AvgScore"
      ]
    },
    "controls": [
      {
        "description": "Expenditure per student (resource control).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "expenditure"
        ]
      },
      {
        "description": "District average income in thousands of USD (socioeconomic control).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "income"
        ]
      },
      {
        "description": "Percent of students qualifying for CalWorks (income assistance) — socioeconomic control.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "calworks"
        ]
      },
      {
        "description": "Percent of students qualifying for reduced-price lunch — socioeconomic control.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "lunch"
        ]
      },
      {
        "description": "Percent of English learners in the district (language proficiency control).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "english"
        ]
      },
      {
        "description": "Computers per student (proxy for technology resources). Calculated as computer / students.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "ComputersPerStudent"
        ]
      },
      {
        "description": "Total district enrollment (control for district size).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "students"
        ]
      },
      {
        "description": "Grade-span indicator of the district (categorical control, e.g., 'KK-06' vs 'KK-08').",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "grades"
        ]
      },
      {
        "description": "County identifier — included as categorical fixed effects to adjust for unobserved regional differences.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "county"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"\n    Transform the raw district-level dataframe to add the variables needed for modeling.\n\n    Produces the following new columns used by the model:\n      - StudentTeacherRatio: students / teachers\n      - AvgScore: mean of read and math\n      - ComputersPerStudent: computer / students\n\n    Also coerces relevant columns to numeric, filters invalid rows (e.g., teachers <= 0),\n    and drops rows missing any variable required for the regression.\n    \"\"\"\n\n    # Make a copy to avoid modifying original\n    df = df.copy()\n\n    # Coerce key numeric columns to numeric (introduce NaN where parsing fails)\n    numeric_cols = ['students', 'teachers', 'computer', 'expenditure', 'income', 'calworks', 'lunch', 'english', 'read', 'math']\n    for col in numeric_cols:\n        if col in df.columns:\n            df[col] = pd.to_numeric(df[col], errors='coerce')\n\n    # Remove rows with invalid or zero teachers (can't compute ratio) or missing test scores\n    if 'teachers' in df.columns:\n        df.loc[df['teachers'] <= 0, 'teachers'] = np.nan\n\n    # Compute dependent variable: average of reading and math scores\n    df['AvgScore'] = df[['read', 'math']].mean(axis=1)\n\n    # Compute student-teacher ratio (students per teacher)\n    df['StudentTeacherRatio'] = df['students'] / df['teachers']\n\n    # Compute computers per student\n    df['ComputersPerStudent'] = df['computer'] / df['students']\n\n    # Keep columns needed for the model\n    required_cols = [\n        'StudentTeacherRatio', 'AvgScore', 'expenditure', 'income', 'calworks', 'lunch',\n        'english', 'ComputersPerStudent', 'students', 'grades', 'county'\n    ]\n\n    # Some of these columns (grades, county) may be non-numeric — that's fine; we only ensure presence\n    missing_required = [c for c in required_cols if c not in df.columns]\n    if missing_required:\n        # If required columns are missing from the input dataset, raise an informative error\n        raise ValueError(f\"Input dataframe is missing required columns for transformation: {missing_required}\")\n\n    # Drop rows with missing values in any of the required model columns\n    df = df.dropna(subset=required_cols)\n\n    # Optionally, convert grades and county to category dtype for modeling\n    df['grades'] = df['grades'].astype('category')\n    df['county'] = df['county'].astype('category')\n\n    # Final sanity filter: keep only plausible StudentTeacherRatio values\n    # (remove extreme/impossible ratios such as >1000 students per teacher)\n    df = df[(df['StudentTeacherRatio'] > 0) & (df['StudentTeacherRatio'] < 1000)]\n\n    # Reset index for cleanliness\n    df = df.reset_index(drop=True)\n\n    return df\n",
  "m_code": "def model(df: pd.DataFrame) -> Any:\n    \"\"\"\n    Fit an OLS model of AvgScore on StudentTeacherRatio controlling for district resources\n    and socioeconomic characteristics. Returns results with robust standard errors (HC3).\n\n    Model formula:\n      AvgScore ~ StudentTeacherRatio + expenditure + income + calworks + lunch + english\n                 + ComputersPerStudent + students + C(grades) + C(county)\n\n    Notes:\n      - County and grades are included as categorical fixed effects using C(...).\n      - Robust (heteroskedasticity-consistent) covariance is applied (HC3).\n    \"\"\"\n    import statsmodels.formula.api as smf\n\n    # Ensure required columns are present\n    formula = (\n        'AvgScore ~ StudentTeacherRatio + expenditure + income + calworks + lunch + english '\n        '+ ComputersPerStudent + students + C(grades) + C(county)'\n    )\n\n    # Fit OLS\n    ols_mod = smf.ols(formula=formula, data=df).fit()\n\n    # Obtain robust covariance (HC3) for heteroskedasticity-robust inference\n    results = ols_mod.get_robustcov_results(cov_type='HC3')\n\n    # Print a concise summary for quick inspection\n    print(results.summary())\n\n    return results\n"
}
